edits.newText:
// B-015: "show the jump-to-now-playing" glyph now also shown when the
// playing track resides in the current folder so accessibility can bring it
// into view without changing folders. The action remains a11y-friendly.
// Debounce logic still controls visibility when the track is outside the
// visible region; the behavior keeps the browser in that folder on activation.
final playingPathExists =
    playingPath != null &&
    playingPath.isNotEmpty;
final inSameFolder = playingPathExists &&
    path != null &&
    p.dirname(playingPath) == path;
final divergent =
    playingPathExists &&
    p.dirname(playingPath) != (path ?? '');
final showJumpGlyph = resolveJumpGlyphVisible(divergent || inSameFolder);
// 12-px vertical padding preserves the crumb baseline; the 44×44
// glyph hit target sits outside it (Material min, B-013).

